python3 - <<'PY'
from pathlib import Path
Path('src/money.ts').write_text("""export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
""")
for renderer in ('invoice', 'report'):
    path = Path(f'src/{renderer}.ts')
    path.write_text(path.read_text().replace(f"import {{ {renderer}Amount }} from './{renderer}Amount';", "import { formatAmount } from './money';").replace(f'{renderer}Amount(cents)', 'formatAmount(cents)').replace(f'{renderer}Amount(row.cents)', 'formatAmount(row.cents)'))
    Path(f'src/{renderer}Amount.ts').unlink()
Path('checks/public.cjs').write_text("""const assert = require('node:assert/strict');
const { formatAmount } = require('../.build/money');
const { renderInvoice } = require('../.build/invoice');
const { renderReport } = require('../.build/report');

const cases = [
  [0, '0.00'],
  [-0, '0.00'],
  [1, '0.01'],
  [9, '0.09'],
  [99, '0.99'],
  [100, '1.00'],
  [123, '1.23'],
  [-1, '-0.01'],
  [-99, '-0.99'],
  [-100, '-1.00'],
  [-123, '-1.23'],
];
for (const [cents, expected] of cases) {
  assert.equal(formatAmount(cents), expected);
  assert.equal(renderInvoice('inv', cents), 'inv: $' + expected);
  assert.equal(renderReport([{ id: 'row', cents }]), 'row,' + expected);
}
assert.equal(renderReport([]), '');
assert.equal(
  renderReport([{ id: 'z', cents: 123 }, { id: 'a', cents: 0 }, { id: 'b', cents: -1 }]),
  'z,1.23\\na,0.00\\nb,-0.01'
);
""")
PY
tsc -p tsconfig.json && node checks/public.cjs
printf '\nSource files:\n'
cat src/*.ts
